func (h *GiveawaysHandler) action(c fiber.Ctx, action string) error {
	r := result.New[*dbgiveaway.Row]()
	ctx := c.Context()

	id, verr := validations.ParseGiveawayIDParam(c.Params("id"))
	if verr != nil {
		captureGiveawaysError(c, r, verr)
		return replyGiveaways(c, r)
	}
	var payload json.RawMessage
	if action == dbgiveaway.PendingActionReroll {
		winners, verr := validations.ParseGiveawayReroll(c.Body())
		if verr != nil {
			captureGiveawaysError(c, r, verr)
			return replyGiveaways(c, r)
		}
		if winners != nil {
			payload, _ = json.Marshal(dbgiveaway.RerollPayload{Winners: *winners})
		}
	}
	row, err := h.Repo.MarkPendingAction(ctx, id, action)
	if err != nil {
		captureGiveawaysError(c, r, err)
		return replyGiveaways(c, r)
	}
	if row == nil {
		r.AddError(giveawayNotFound())
		return replyGiveaways(c, r)
	}
	h.emit(ctx, row, action, payload)
	r.SetData(row)
	r.SetSource(result.SourceDB, giveawaysSourceDetail)
	return replyGiveaways(c, r)
}
```

