```
fn map_close_code(reason: Option<DisconnectReason>) -> (i32, String, bool, bool) {
    // devuelve (code, reason_str, by_remote, retryable)
    use songbird::model::CloseCode as VC;
    match reason {
        None | Some(DisconnectReason::Requested) => (1000, "requested".into(), false, false),
        Some(DisconnectReason::WsClosed(Some(c))) => {
            // `SessionInvalid` queda FUERA a propósito. Discord ya invalidó la
            // sesión, así que reconectar con la `ConnectionInfo` cacheada es
            // imposible por construcción: el reintento sólo puede volver a
            // fallar. Y como cada nueva caída cancelaba y relanzaba la tarea, el
            // bucle no terminaba nunca — de ahí que `all attempts exhausted` no
            // llegara a aparecer pese a los fallos. La recuperación real llega
            // por el `WebSocketClosedEvent` de abajo: `PlayerClosed.ts` de
            // music-module lo atiende y manda un `update_voice` fresco.
            //
            // Ojo al discriminar: `DisconnectReason::Io` también mapea al código
            // 4006 unas líneas más abajo y SÍ debe seguir reintentándose. La
            // distinción es por variante del enum, nunca por el código; lo fija
            // `session_invalid_and_io_share_4006_but_not_retryability`.
            let retryable = matches!(
                c,
                VC::SessionTimeout | VC::VoiceServerCrash | VC::ServerNotFound
            );
            (c as i32, format!("{c:?}"), true, retryable)
        }
        Some(DisconnectReason::WsClosed(None)) => (4000, "wsClosedUnknown".into(), true, true),
        Some(DisconnectReason::TimedOut) => (4009, "timedOut".into(), true, true),
        Some(DisconnectReason::Io) => (4006, "io".into(), true, true),
        Some(DisconnectReason::AttemptDiscarded) => (4000, "attemptDiscarded".into(), true, false),
        Some(DisconnectReason::ProtocolViolation) => {
            (4012, "protocolViolation".into(), true, false)
        }
        Some(DisconnectReason::Internal) => (4000, "internal".into(), true, false),
        Some(_) => (4000, "unknown".into(), true, false),
    }
}
```

