// GreeterBehavior captures runtime behaviour toggles per greeter event.
// (`send_dm` was removed by the Node feat DM-support commit 145424f — the
// richer `dm` block below supersedes it. `mention_user` went the same way: the
// mention is not a toggle, it is written into the message text as `{user}`.
// Documents stored before the removal still carry both fields in Mongo; nobody
// reads them and the driver ignores what the struct does not declare.)
type GreeterBehavior struct {
	// DeleteAfterSeconds rige SOLO el mensaje de canal. El privado tiene el
	// suyo en GreeterDM: son dos envíos distintos y compartir el campo hacía
	// que limpiar el canal de bienvenidas borrara también el MD del historial
	// del usuario.
	DeleteAfterSeconds *int `bson:"delete_after_seconds" json:"delete_after_seconds"`
}

// GreeterDM mirrors the per-message `dm` block the Node greeter added (feat
// DM support, commit 145424f, 2026-07-15): an independent DM copy of the
// channel message. Reutiliza GreeterMessage / GreeterEmbed / GreeterImage —
// misma FORMA que sus equivalentes de canal, pero `Image` de aquí abajo es un
// bloque APARTE del `Image` de `GreeterMessageConfig`, no una copia por
// referencia: comparten struct, no dato.
//
// Desde v14 el privado ofrece las MISMAS opciones que el canal:
// `Message.Mode` ya no está restringido a plain|embed (como lo estuvo hasta
// entonces en el lado Node) sino a los cuatro `GreeterMessageMode`, y trae su
// propio `Image` con su propio canvas.
type GreeterDM struct {
	Enabled bool           `bson:"enabled" json:"enabled"`
	Message GreeterMessage `bson:"message" json:"message"`
	// Bloque de imagen del privado (v14) — ver el comentario del struct.
	// `normalizeGreeterImage` rellena sus huecos y `validateGreeterImage` sus
	// topes, exactamente igual que el `Image` de canal.
	Image GreeterImage `bson:"image" json:"image"`
	Embed GreeterEmbed `bson:"embed" json:"embed"`
	// Borrado automático del MD (v12). Nil = no se borra, que es el default y
	// lo que un doc anterior a v12 decodifica: NO se backfillea desde
	// `Behavior.DeleteAfterSeconds` a propósito — ver el changelog de
	// `DBModuleSchemaVersions.greeter` en library-shared.
	DeleteAfterSeconds *int `bson:"delete_after_seconds" json:"delete_after_seconds"`
}

// GreeterMessageConfig matches `DBGreeterMessageConfig` — used for the
// welcome, goodbye and boost events.
type GreeterMessageConfig struct {
	Enabled   bool            `bson:"enabled"     json:"enabled"`
	ChannelID *string         `bson:"channel_id"  json:"channel_id"`
	Message   GreeterMessage  `bson:"message"     json:"message"`
	Embed     GreeterEmbed    `bson:"embed"       json:"embed"`
	Image     GreeterImage    `bson:"image"       json:"image"`
	Behavior  GreeterBehavior `bson:"behavior"    json:"behavior"`
	DM        GreeterDM       `bson:"dm"          json:"dm"`
}

// JoinRoles toggles the auto-role assignment on member join. `delay_seconds`
// (nullable, added by Node commit 145424f) delays the assignment.
type JoinRoles struct {
	Enabled      bool     `bson:"enabled"       json:"enabled"`
	RolesID      []string `bson:"roles_id"      json:"roles_id"`
	DelaySeconds *int     `bson:"delay_seconds" json:"delay_seconds"`
}

// GreeterVariables advertises the placeholder tokens the renderer accepts in
// message bodies (e.g. `{user}`, `{guild_name}`).
type GreeterVariables struct {
	Allowed []string `bson:"allowed" json:"allowed"`
}

// GreeterCaptcha holds the captcha gate config. `VerifiedRoleID` is a
// pointer because the Node service encodes the absence as JSON null (not
// empty string). `ButtonLabel` max 80 chars, límite de Discord para el
// label de un botón.
