	WelcomeEmbed   *GreeterCaptchaWelcomeEmbed `bson:"welcome_embed,omitempty" json:"welcome_embed"`
	// GhostPing: el bot menciona al nuevo miembro en el canal del captcha y
	// borra el mensaje al instante — el ping llega igual y arrastra al usuario
	// al canal a leer el mensaje del servidor. NO es un puntero: `false` es el
	// comportamiento previo, así que un doc sin la clave decodifica ya correcto.
	GhostPing bool `bson:"ghost_ping" json:"ghost_ping"`
}

// Embed simple que acompaña al botón de verificación en `ChannelID`. `Color`
// se almacena como hex string (`#5165F7`); el bot Node convierte a int.
type GreeterCaptchaWelcomeEmbed struct {
	Title       string  `bson:"title"       json:"title"`
	Description string  `bson:"description" json:"description"`
	Color       string  `bson:"color"       json:"color"`
	Footer      *string `bson:"footer"      json:"footer"`
}

// GreeterDefaultBoostReactionEmoji es el emoji de fábrica de la reacción al
// boost: el "🎉" unicode. Mismo motivo que ModmailDefaultDmAckEmoji para NO
// mapearlo con applyEmojiMap: Discord valida una reacción contra quien
// reacciona, así que un bot custom sin el emoji de la aplicación KenaBot
// muere con un `10014 Unknown Emoji`, y en silencio.
const GreeterDefaultBoostReactionEmoji = "🎉"

// GreeterBoostReaction mirrors `DBGreeterBoostReaction` — la reacción con la
// que el bot marca SU PROPIO mensaje de agradecimiento por el boost, el que
// publica en `Boost.ChannelID`, no el mensaje de sistema que Discord publica
// al boostear (ese sólo dispara el handler). Sin mensaje de canal no hay
// reacción: si `Boost.Enabled` está apagado, si no hay canal o si el envío
// falla, no queda nada que marcar.
//
// A diferencia de `ModmailDmAckReaction`, nace APAGADO: allí un ticket sin
// acuse se ve igual que un bot caído, aquí no falta nada, y una reacción que
// apareciera sola en un guild que ya tenía el módulo sería un cambio de
// comportamiento no pedido. Por eso el bloque NO es puntero (a diferencia de
// su análogo en modmail): su valor cero (`enabled:false, emoji:""`) YA es el
// comportamiento previo a v15, así que un doc anterior al campo decodifica
// correcto sin distinguir "ausente" de "apagado a mano". `NormalizeGreeter`
// sólo repone el emoji cuando llega en blanco -reaccionar con "" es un 400
// seguro de Discord-, nunca `Enabled`.
type GreeterBoostReaction struct {
	Enabled bool   `bson:"enabled" json:"enabled"`
	Emoji   string `bson:"emoji"   json:"emoji"`
}

// ModuleGreeter matches `DBModuleGreeter`.
type ModuleGreeter struct {
	SchemaVersion int  `bson:"schema_version" json:"schema_version"`
	Enabled       bool `bson:"enabled"        json:"enabled"`
	// EnabledSince es la fecha de la PRIMERA activación del módulo en este
	// guild — WRITE-ONCE: se estampa al activar por primera vez y no se
	// reescribe nunca (ni al desactivar ni al reactivar). Sostiene el
	// derecho legacy: un guild que activó greeter antes del corte de
	// `globals.module_premium_cutoffs` conserva el módulo entero gratis.
	// `nil` (campo ausente en Mongo) = nunca activado.
	EnabledSince *JSONDate            `bson:"enabled_since,omitempty" json:"enabled_since"`
	Welcome      GreeterMessageConfig `bson:"welcome"        json:"welcome"`
	Goodbye      GreeterMessageConfig `bson:"goodbye"        json:"goodbye"`
	Boost        GreeterMessageConfig `bson:"boost"          json:"boost"`
	// BoostReaction mirrors `DBGreeterBoostReaction` — reacción al mensaje de
	// boost que el bot publica en `Boost.ChannelID`; sin ese mensaje no hay
	// reacción. Valor cero == apagado, que ES el comportamiento previo a v15:
	// NO es puntero, a diferencia del `DmAckReaction` de modmail (ver
	// GreeterBoostReaction).
	BoostReaction GreeterBoostReaction `bson:"boost_reaction" json:"boost_reaction"`
	JoinRoles     JoinRoles            `bson:"join_roles"     json:"join_roles"`
	// `omitempty` SOLO en bson (campo ausente en Mongo cuando no hay bloque).
	// En json va sin omitempty, igual que el resto de nullables: la regla del
	// fichero es que la salida JSON conserve la forma del tipo TS, así que
	// `captcha` tiene que emitir `null` y no desaparecer. Con omitempty, un
	// consumidor que lea `data.captcha.enabled` recibía `undefined` en vez de
	// `null` y reventaba con un TypeError.
	Captcha   *GreeterCaptcha  `bson:"captcha,omitempty" json:"captcha"`
	Variables GreeterVariables `bson:"variables"      json:"variables"`
	UpdatedAt JSONDate         `bson:"updated_at"     json:"updated_at"`
}

// DefaultGreeterVariables es la allowlist canónica de tokens de sustitución.
// Vive aquí (y no solo en el mock) porque el normalizador de documentos legacy
// también la necesita, y `mocks` importa `dbguild`, no al revés.
func DefaultGreeterVariables() []string {
	return []string{"user", "user_name", "user_id", "guild", "guild_name", "member_count"}
}

// normalizeGreeterMessageConfig rellena los huecos de UN bloque de mensaje
// (welcome / goodbye / boost): el modo de mensaje (canal y dm), el bloque
// `image` -canal Y dm, misma forma, ver normalizeGreeterImage- y, desde v13,
// reescala el `radius` de cada elemento del canvas de CANAL. Ver
// NormalizeGreeter.
//
// El reescalado de radius es de otra naturaleza que el resto de esta función:
// lo demás sólo rellena AUSENCIAS (`mode: ""`, `elements: nil`) sin tocar
// nada que ya tuviera un valor, así que da igual cuántas veces se aplique.
// `radius` en cambio SUSTITUYE un número ya existente por otro con
// significado distinto (píxeles → porcentaje del lado corto del propio
// elemento) -es la primera normalización del módulo que toca el CONTENIDO de
// `canvas.elements`, no sólo sus huecos- y por construcción NO es idempotente
// si se le vuelve a pasar su propia salida: un segundo paso volvería a
// dividir un porcentaje ya migrado entre la mitad del lado corto del
// elemento, retorciendo la redondez en cada lectura. Por eso esta función no
// decide sola cuándo correr: depende enteramente de que quien la invoca
// (NormalizeGreeter, y antes que ella los call sites de
// module_greeter_repository.go) sólo lo haga cuando
// `SchemaVersion < SchemaVersionGreeter`, para que el reescalado corra como
// mucho una vez por documento.
func normalizeGreeterMessageConfig(c *GreeterMessageConfig, migrateRadius bool) {
	// Enum vacío: un doc legacy trae `mode: ""`, que no casa con ningún modo
	// del renderer — el bot no publica nada y el dashboard lo pinta como
	// `plain`. Alinear con lo que ve el usuario.
	if c.Message.Mode == "" {
		c.Message.Mode = GreeterModePlain
	}
	if c.DM.Message.Mode == "" {
		c.DM.Message.Mode = GreeterModePlain
	}

	// Huecos del bloque `image`: canal y privado comparten exactamente la
	// misma normalización -misma struct `GreeterImage` desde v14, ver
	// GreeterDM-, así que se extrae a una función y se llama dos veces en vez
	// de duplicar el cuerpo: duplicarlo es cómo un ajuste futuro se aplica a
	// uno de los dos bloques y se olvida en el otro.
	normalizeGreeterImage(&c.Image)
	normalizeGreeterImage(&c.DM.Image)

	// v13: `radius` pasa de píxeles a porcentaje (0-100) del lado corto DEL
	// ELEMENTO -no del canvas: dos elementos del mismo lienzo pueden tener
	// cajas bien distintas-. `nil` se deja tal cual: no hay valor que migrar,
	// y convertir la ausencia inventaría un dato que el usuario nunca puso;
	// sólo se reescala lo que ya traía un número, con la misma fórmula que el
	// changelog de `DBModuleSchemaVersions.greeter` (v13) en library-shared.
	//
	// `migrateRadius` lo decide `NormalizeGreeter` mirando la versión DEL
	// DOCUMENTO, no la del código. Antes bastaba con que el repositorio
	// llamara sólo cuando `SchemaVersion < SchemaVersionGreeter`, y eso dejó
	// de ser suficiente en cuanto la constante subió por encima de 13: un
	// documento v13 o v14 -ya en porcentaje- volvía a entrar por aquí en el
	// siguiente PATCH y se reescalaba una segunda vez. Con cajas cuadradas se
	// disimula (satura a 100), pero un `radius: 29` en una caja de 160x82 se
	// convertía en 71. La versión del documento es el único dato que dice si
	// ese número son píxeles o ya un porcentaje.
	//
	// SÓLO el canvas de CANAL (`c.Image`), nunca el del privado
	// (`c.DM.Image`): ese bloque nace en v14, así que ningún documento lo ha
	// contenido jamás en píxeles -no hay nada legacy que migrar en él-, y
	// pasarlo por esta fórmula dividiría un porcentaje recién escrito por el
	// usuario como si fuera un píxel, corrompiéndolo en la primera lectura.
	// NO lo "arregles" para que quede simétrico con `normalizeGreeterImage` de
	// arriba: la asimetría aquí es intencional, no un olvido.
	if !migrateRadius {
		return
	}
	for i := range c.Image.Canvas.Elements {
		el := &c.Image.Canvas.Elements[i]
		if el.Radius == nil {
			continue
		}
		*el.Radius = migrateRadiusPxToPercent(*el.Radius, el.Width, el.Height)
	}
}

// normalizeGreeterImage rellena los huecos de UN bloque `image` (el de canal
// o el del privado — misma struct `GreeterImage` desde v14, ver GreeterDM):
// modo vacío pasa a básico, `elements` nil pasa a slice vacío -si no, sale
// `null` en JSON y revienta cualquier `.map()` del dashboard, o un `for..of`
// sobre null en el bot- y el lienzo se acota a un tamaño válido, igual que al
// escribir.
//
// Un lienzo 0x0 no es una configuración válida, es un bloque que nunca se
// escribió. Los mismos defaults que `mocks.NewModuleGreeter`.
//
// El techo NO es cosmética: el renderer hace `createCanvas(width, height)` y
// eso es memoria nativa fuera del heap de V8. Un documento ya almacenado con
// `width: 50000` -escrito antes de que la validación existiera- pedía ~10 GB
// y tumbaba el proceso que sirve a todos los guilds, así que hay que
// acotarlo también al LEER, no sólo al escribir.
//
// NO toca `radius`: ese reescalado es v13, no es aditivo y sólo aplica al
// canvas de CANAL — se queda en el llamador (normalizeGreeterMessageConfig),
// no aquí, para que esta función siga sirviendo tal cual al canvas del
// privado, que nunca ha tenido píxeles que migrar.
func normalizeGreeterImage(img *GreeterImage) {
	if img.Mode == "" {
		img.Mode = GreeterImageBasic
	}
	if img.Canvas.Elements == nil {
		img.Canvas.Elements = []GreeterImageElement{}
	}
	img.Canvas.Width = clampCanvasSide(img.Canvas.Width, 1024)
	img.Canvas.Height = clampCanvasSide(img.Canvas.Height, 500)
}

// migrateRadiusPxToPercent traduce un `radius` legacy en píxeles al nuevo
// porcentaje (0-100) del lado corto de la caja `width` x `height` -la del
// ELEMENTO, no la del canvas-, con la misma fórmula que el changelog de
// `DBModuleSchemaVersions.greeter` (v13) en library-shared:
// `pct = round(clamp(px / (min(w,h)/2) * 100, 0, 100))`. Una caja degenerada
// (ancho o alto <= 0 -no debería existir, pero un documento viejo puede
// traerla-) no tiene "mitad del lado corto" con la que dividir -daría +Inf o
// NaN-, así que cae a 0 en vez de propagar basura al resto del pipeline.
func migrateRadiusPxToPercent(px, width, height float64) float64 {
	shortSide := math.Min(width, height)
	if shortSide <= 0 {
		return 0
	}
	pct := px / (shortSide / 2) * 100
	if pct < 0 {
		pct = 0
	} else if pct > 100 {
		pct = 100
	}
	return math.Round(pct)
}

// MaxCanvasSide es el lado máximo del lienzo del greeter. 4096x4096 en RGBA
// son ya 64 MB de memoria nativa; por encima se entra en territorio de OOM del
// contenedor. El bot aplica el mismo techo al renderizar.
const MaxCanvasSide = 4096

func clampCanvasSide(value, fallback int) int {
	if value <= 0 {
		return fallback
	}
	if value > MaxCanvasSide {
		return MaxCanvasSide
	}
	return value
}

// NormalizeGreeter rellena los campos que un documento legacy dejó a cero o a
// nil, SIN pisar nada que tenga valor. Es lo que separa "migrar" de "resetear":
// sustituir el subdoc entero por `mocks.NewModuleGreeter()` solo es correcto
// cuando el bloque no existe (`schema_version == 0`); para un doc v9/v10 con
// config real borraría los ajustes del usuario.
//
// Idempotente, incluido `radius`: el reescalado de píxeles a porcentaje (v13)
// se decide aquí mirando `m.SchemaVersion`, la versión DEL DOCUMENTO, no la
// del código. Antes lo decidía el llamador con `SchemaVersion <
// SchemaVersionGreeter`, y eso dejó de proteger nada en cuanto la constante
// pasó de 13: un doc v13/v14 seguía entrando por ese guard y se reescalaba una
// segunda vez. Ver el comentario largo en `normalizeGreeterMessageConfig`.
func NormalizeGreeter(m *ModuleGreeter) {
	if m == nil {
		return
	}
	// Sólo los documentos ANTERIORES a v13 traen `radius` en píxeles. Un
	// `SchemaVersion` 0 (documento sin versionar, previo a todo esto) también
	// cuenta: nació mucho antes que el porcentaje.
	migrateRadius := m.SchemaVersion < SchemaVersionGreeterRadiusPercent

	normalizeGreeterMessageConfig(&m.Welcome, migrateRadius)
	normalizeGreeterMessageConfig(&m.Goodbye, migrateRadius)
	normalizeGreeterMessageConfig(&m.Boost, migrateRadius)

	// Reacción al boost: independiente de `m.Boost.Enabled`, así que sólo se
	// repone el emoji en blanco (ausente o sólo espacios) -reaccionar con ""
	// es un 400 seguro de Discord-, nunca `Enabled`: el bloque nace apagado y
	// apagado ES el comportamiento previo a v15.
	if strings.TrimSpace(m.BoostReaction.Emoji) == "" {
		m.BoostReaction.Emoji = GreeterDefaultBoostReactionEmoji
	}

	m.JoinRoles.RolesID = ensureStrSlice(m.JoinRoles.RolesID)
	if m.Variables.Allowed == nil {
		m.Variables.Allowed = DefaultGreeterVariables()
	}
}

package handlers

import (
	"strconv"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// ModuleGreeterHandler wires the two greeter endpoints behind a single
// struct.
//
// Mirrors `module-greeter-controller.ts` in the Node service.
type ModuleGreeterHandler struct {
	Repo mongorepo.ModuleGreeterRepo
}

// NewModuleGreeterHandler builds the handler.
func NewModuleGreeterHandler(repo mongorepo.ModuleGreeterRepo) *ModuleGreeterHandler {
	return &ModuleGreeterHandler{Repo: repo}
}

// Get mirrors `getModuleGreeterController`. Returns the full greeter
// subdoc (default-filled) with source headers stamped. Honors the
// optional `?force=true` query that evicts the cache before reading.
func (h *ModuleGreeterHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleGreeter]()
	ctx := c.Context()

	force, _ := strconv.ParseBool(c.Query("force"))

