1	package validations
2	
3	import (
4		"regexp"
5		"strconv"
6	
7		"kena.bot/api-db-go/internal/domain/dbguild"
8		apierrors "kena.bot/api-db-go/internal/domain/errors"
9	)
10	
11	// UpdateModuleTTSBody es el cuerpo del PATCH del módulo de texto a voz. El
12	// handler lo decodifica con `DisallowUnknownFields` (el equivalente del
13	// `.strict()` de zod: una clave desconocida es un 400) y luego vuelve a
14	// decodificar el MISMO cuerpo crudo como `map[string]any`, que es lo que el
15	// repositorio mezcla con `mongo.MergeDeepJSON` por PRESENCIA de clave.
16	//
17	// TODOS los campos son punteros: un nil significa «no tocar», y así un `false`,
18	// un `0` o un `null` explícitos SÍ se aplican. Igual que en el resto de módulos,
19	// el PATCH NO expone `schema_version` ni `updated_at` —los estampa el
20	// repositorio en cada escritura— ni `enabled_since`, que es WRITE-ONCE del
21	// servidor.
22	type UpdateModuleTTSBody struct {
23		Enabled        *bool    `json:"enabled,omitempty"`
24		RequireVoice   *bool    `json:"require_voice,omitempty"`
25		Language       *string  `json:"language,omitempty"`
26		Speed          *float64 `json:"speed,omitempty"`
27		SayName        *bool    `json:"say_name,omitempty"`
28		MaxChars       *int     `json:"max_chars,omitempty"`
29		RepeatedChars  *int     `json:"repeated_chars,omitempty"`
30		SkipEmoji      *bool    `json:"skip_emoji,omitempty"`
31		RequiredRoleID *string  `json:"required_role_id,omitempty"`
32		// El mapa `commands` se mezcla POR CLAVE (`MergeDeepJSON` sin replace), así
33		// que un PATCH con un solo subcomando no borra los otros tres. Divergencia
34		// deliberada frente a music, que reemplaza el mapa entero desde su `Set()`.
35		CommandsGlobal *dbguild.TTSCommandAccess      `json:"commands_global,omitempty"`
36		Commands       *map[string]dbguild.TTSCommand `json:"commands,omitempty"`
37	}
38	
39	// ttsLanguageRe acepta un código ISO-639-1 con región opcional (`es`, `en`,
40	// `pt-BR`). El nodo de síntesis usa el código de idioma como selector de timbre,
41	// así que cualquier cosa fuera de esta forma no es un idioma raro: es un
42	// documento que hará desaparecer los mensajes en silencio.
43	var ttsLanguageRe = regexp.MustCompile(`^[a-z]{2}(-[A-Za-z0-9]{2,4})?$`)
44	
45	// ValidateUpdateModuleTTS comprueba los límites que el merge no puede: el
46	// repositorio escribe lo que le llega, así que un `speed: 9` o un `max_chars:
47	// 5000` se guardarían tal cual y el nodo rechazaría cada frase después, ya sin
48	// nadie mirando. Un puntero nil es «no tocar este campo» y no se valida.
49	//
50	// Los techos son los del nodo (`KENA_LINK_TTS_MAX_CHARS`, rango de velocidad),
51	// no una preferencia: pasarse de ellos no da audio, da rechazo.
52	func ValidateUpdateModuleTTS(body *UpdateModuleTTSBody) *apierrors.CustomError {
53		if body == nil {
54			return nil
55		}
56	
57		if body.Language != nil && !ttsLanguageRe.MatchString(*body.Language) {
58			return zodItemError("Invalid language: expected an ISO-639-1 code with an optional region (e.g. `es`, `pt-BR`)", "language")
59		}
60	
61		if body.Speed != nil {
62			if *body.Speed < dbguild.MinTTSSpeed {
63				return zodItemError("Too small: expected number to be >="+strconv.FormatFloat(dbguild.MinTTSSpeed, 'g', -1, 64), "speed")
64			}
65			if *body.Speed > dbguild.MaxTTSSpeed {
66				return zodItemError("Too big: expected number to be <="+strconv.FormatFloat(dbguild.MaxTTSSpeed, 'g', -1, 64), "speed")
67			}
68		}
69	
70		if body.MaxChars != nil {
71			if *body.MaxChars < 1 {
72				return zodItemError("Too small: expected number to be >=1", "max_chars")
73			}
74			if *body.MaxChars > dbguild.MaxTTSChars {
75				return zodItemError("Too big: expected number to be <="+strconv.Itoa(dbguild.MaxTTSChars), "max_chars")
76			}
77		}
78	
79		if body.RepeatedChars != nil {
80			if *body.RepeatedChars < 0 {
81				return zodItemError("Too small: expected number to be >=0", "repeated_chars")
82			}
83			if *body.RepeatedChars > dbguild.MaxTTSRepeatedChars {
84				return zodItemError("Too big: expected number to be <="+strconv.Itoa(dbguild.MaxTTSRepeatedChars), "repeated_chars")
85			}
86		}
87	
88		// Los dos nullables de primer nivel. `null` (puntero nil) es «quitar el
89		// canal / no exigir rol» y es legítimo; la cadena vacía llega del formulario
90		// del dashboard cuando el selector se deja sin elegir y significa lo mismo.
91		// Lo que no puede pasar es un id que no sea un snowflake.
92		for _, f := range []struct {
93			value    *string
94			property string
95		}{
96			{body.RequiredRoleID, "required_role_id"},
97		} {
98			if f.value == nil || *f.value == "" {
99				continue
100			}
101			if !snowflakeRe.MatchString(*f.value) {
102				return zodItemError("Invalid snowflake: expected a 17-20 digit id", f.property)
103			}
104		}
105	
106		return nil
107	}
108

