// handler lo decodifica con `DisallowUnknownFields` (el equivalente del
// `.strict()` de zod: una clave desconocida es un 400) y luego vuelve a
// decodificar el MISMO cuerpo crudo como `map[string]any`, que es lo que el
// repositorio mezcla con `mongo.MergeDeepJSON` por PRESENCIA de clave.
//
// TODOS los campos son punteros: un nil significa «no tocar», y así un `false`,
// un `0` o un `null` explícitos SÍ se aplican. Igual que en el resto de módulos,
// el PATCH NO expone `schema_version` ni `updated_at` —los estampa el
// repositorio en cada escritura— ni `enabled_since`, que es WRITE-ONCE del
// servidor.
type UpdateModuleTTSBody struct {
	Enabled        *bool    `json:"enabled,omitempty"`
	RequireVoice   *bool    `json:"require_voice,omitempty"`
	Language       *string  `json:"language,omitempty"`
	Speed          *float64 `json:"speed,omitempty"`
	SayName        *bool    `json:"say_name,omitempty"`
	MaxChars       *int     `json:"max_chars,omitempty"`
	RepeatedChars  *int     `json:"repeated_chars,omitempty"`
	SkipEmoji      *bool    `json:"skip_emoji,omitempty"`
	RequiredRoleID *string  `json:"required_role_id,omitempty"`
	// El mapa `commands` se mezcla POR CLAVE (`MergeDeepJSON` sin replace), así
	// que un PATCH con un solo subcomando no borra los otros tres. Divergencia
	// deliberada frente a music, que reemplaza el mapa entero desde su `Set()`.
	CommandsGlobal *dbguild.TTSCommandAccess      `json:"commands_global,omitempty"`
	Commands       *map[string]dbguild.TTSCommand `json:"commands,omitempty"`
}

// ttsLanguageRe acepta un código ISO-639-1 con región opcional (`es`, `en`,
// `pt-BR`). El nodo de síntesis usa el código de idioma como selector de timbre,
// así que cualquier cosa fuera de esta forma no es un idioma raro: es un
// documento que hará desaparecer los mensajes en silencio.
var ttsLanguageRe = regexp.MustCompile(`^[a-z]{2}(-[A-Za-z0-9]{2,4})?$`)

// ValidateUpdateModuleTTS comprueba los límites que el merge no puede: el
// repositorio escribe lo que le llega, así que un `speed: 9` o un `max_chars:
// 5000` se guardarían tal cual y el nodo rechazaría cada frase después, ya sin
// nadie mirando. Un puntero nil es «no tocar este campo» y no se valida.
//
// Los techos son los del nodo (`KENA_LINK_TTS_MAX_CHARS`, rango de velocidad),
// no una preferencia: pasarse de ellos no da audio, da rechazo.
func ValidateUpdateModuleTTS(body *UpdateModuleTTSBody) *apierrors.CustomError {
	if body == nil {
		return nil
	}

	if body.Language != nil && !ttsLanguageRe.MatchString(*body.Language) {
		return zodItemError("Invalid language: expected an ISO-639-1 code with an optional region (e.g. `es`, `pt-BR`)", "language")
	}

	if body.Speed != nil {
		if *body.Speed < dbguild.MinTTSSpeed {
			return zodItemError("Too small: expected number to be >="+strconv.FormatFloat(dbguild.MinTTSSpeed, 'g', -1, 64), "speed")
		}
		if *body.Speed > dbguild.MaxTTSSpeed {
			return zodItemError("Too big: expected number to be <="+strconv.FormatFloat(dbguild.MaxTTSSpeed, 'g', -1, 64), "speed")
		}
	}

	if body.MaxChars != nil {
		if *body.MaxChars < 1 {
			return zodItemError("Too small: expected number to be >=1", "max_chars")
		}
		if *body.MaxChars > dbguild.MaxTTSChars {
			return zodItemError("Too big: expected number to be <="+strconv.Itoa(dbguild.MaxTTSChars), "max_chars")
		}
	}

	if body.RepeatedChars != nil {
		if *body.RepeatedChars < 0 {
			return zodItemError("Too small: expected number to be >=0", "repeated_chars")
		}
		if *body.RepeatedChars > dbguild.MaxTTSRepeatedChars {
			return zodItemError("Too big: expected number to be <="+strconv.Itoa(dbguild.MaxTTSRepeatedChars), "repeated_chars")
		}
	}

	// Los dos nullables de primer nivel. `null` (puntero nil) es «quitar el
	// canal / no exigir rol» y es legítimo; la cadena vacía llega del formulario
	// del dashboard cuando el selector se deja sin elegir y significa lo mismo.
	// Lo que no puede pasar es un id que no sea un snowflake.
	for _, f := range []struct {
		value    *string
		property string
	}{
		{body.RequiredRoleID, "required_role_id"},
	} {
		if f.value == nil || *f.value == "" {
			continue
		}
		if !snowflakeRe.MatchString(*f.value) {
			return zodItemError("Invalid snowflake: expected a 17-20 digit id", f.property)
		}
	}

	return nil
}

