package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleTempvoiceBody mirrors the Node `updateModuleTempVoiceSchema` (a
// `.strict()` object of `.optional()` fields). Unlike the READ schema, the
// PATCH schema excludes only `schema_version` and `updated_at` (server-managed).
// The top-level `name_blacklist`, `panel` and `command_mode` (added in v3/v4/v7)
// ARE patchable — omitting them here made the strict decoder reject them as
// `unrecognized_keys` on any PATCH that included them (e.g. saving the panel from
// the dashboard) → 400. Every field is a pointer so the strict decoder can validate
// the shape; the handler then re-decodes the SAME raw body as `map[string]any`,
// which the repository merges into the existing subdoc via
// `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides the
// stored value; nested objects recurse (so a partial
// `{"defaults":{"bitrate":96000}}` PATCH preserves the other defaults);
// slices (`creators`) replace wholesale; maps merge per-key.
//
// PER OLA-3 NOTE: the greeter/logs/music bodies bind via Fiber's default
// decoder (silently drops unknown keys, parity with Mongoose) — only
// modmail/tempvoice/giveaway/moderation carry the strict unknown-key
// rejection. The nested field types are the full `dbguild.Tempvoice*`
// shapes: every zod PATCH sub-schema matches its parent type
// field-for-field, so no valid key is rejected. Go's json decoder does
// NOT enforce zod's REQUIRED-ness inside a present nested object, so a
// partial command entry that Node would 400 is accepted here and the
// missing leaves stay zero — the same non-strict-required behaviour
// every Go module body has.
type UpdateModuleTempvoiceBody struct {
	Enabled        *bool                                `json:"enabled,omitempty"`
	Creators       *[]dbguild.TempvoiceCreator          `json:"creators,omitempty"`
	NameBlacklist  *[]string                            `json:"name_blacklist,omitempty"`
	Panel          *dbguild.TempvoicePanel              `json:"panel,omitempty"`
	CommandMode    *dbguild.TempvoiceCommandMode        `json:"command_mode,omitempty"`
	Defaults       *dbguild.TempvoiceDefaults           `json:"defaults,omitempty"`
	CommandsGlobal *dbguild.TempvoiceCommandAccess      `json:"commands_global,omitempty"`
	Commands       *map[string]dbguild.TempvoiceCommand `json:"commands,omitempty"`
}

package mongo

import (
	"context"
	stderrors "errors"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"

	"kena.bot/api-db-go/internal/domain/dbguild"
	"kena.bot/api-db-go/internal/domain/mocks"
	"kena.bot/api-db-go/internal/infrastructure/locker"
	"kena.bot/api-db-go/internal/infrastructure/redis"
)

// ModuleGreeterRepository owns reads / writes against the `module_greeter`
// subdoc of the `guilds` collection plus its dedicated Redis cache.
//
// Cache layout (matches Node's `DBModuleCache`):
//
//	bots:{botId}:guilds:{guildId}:modules:greeter    HASH (TTL: OneHour)
//
// Source-detail strings mirror the Node values:
//
//	cache → "redis:cache.db.module"
//	db    → "mongo.guild.module_greeter"
const (
	SourceDetailModuleGreeterCache = "redis:cache.db.module"
	SourceDetailModuleGreeterDB    = "mongo.guild.module_greeter"
)

// ModuleGreeterRepository is the greeter-specific facade. Mirrors the
// Node `ModuleGreeterRepository` class (which delegates to a shared
// `ModuleRepository` for the cache+projection dance; we inline that
// logic here for fewer indirections).
type ModuleGreeterRepository struct {
	coll  *mongo.Collection
	cache *redis.ModuleCache
	lk    *locker.Locker
}

func (r *ModuleGreeterRepository) WithLocker(lk *locker.Locker) *ModuleGreeterRepository {
	r.lk = lk
	return r
}

func (r *ModuleGreeterRepository) lockKey(key string) func() {
	if r.lk != nil {
		return r.lk.Lock(key)
	}
	return locker.LocalOnly(key)
}

// NewModuleGreeterRepository wires the cache + collection.
func NewModuleGreeterRepository(db *mongo.Database, cache *redis.ModuleCache) *ModuleGreeterRepository {
	return &ModuleGreeterRepository{
		coll:  db.Collection("guilds"),
		cache: cache,
	}
}

// FindModule returns the greeter subdoc, cache-first. On cache miss
// it falls back to Mongo with a `module_greeter` projection, fills any
// defaulted fields via `mocks.NewModuleGreeter()`, and writes the
// result to cache with TTL=OneHour.
func (r *ModuleGreeterRepository) FindModule(ctx context.Context, botID, guildID string, force bool) (*Sourced[dbguild.ModuleGreeter], error) {
	// `force` evicts the cache before the read so the slow path
	// rebuilds from Mongo. Mirrors the Node `findModule({ force: true })`.
	if force {
		_ = r.cache.DeleteModule(ctx, botID, guildID, "greeter")
	}

	// Cache fast-path.
	if !force {
		if cached, err := r.cache.GetModule(ctx, botID, guildID, "greeter"); err == nil && cached != nil {
			var g dbguild.ModuleGreeter
			// v13 (radius px→%) es una migración de UNIDADES, no sólo de
			// forma: sin el chequeo de versión, un doc cacheado con
			// SchemaVersion < SchemaVersionGreeter serviría `radius` en
			// píxeles justo donde el dashboard y el bot ya esperan
			// porcentaje, y lo haría durante todo el TTL (una hora) en vez
			// de sólo hasta el siguiente miss. `SchemaVersion != 0` ya no
			// basta para considerarlo "fresco": además tiene que estar en la
			// versión actual o por encima, o se trata igual que un parse
			// fallido -se borra y se cae al camino lento, que sí normaliza
			// antes de re-cachear.
			if err := mapToModuleGreeter(cached, &g); err == nil && g.SchemaVersion != 0 && g.SchemaVersion >= dbguild.SchemaVersionGreeter {
				return &Sourced[dbguild.ModuleGreeter]{
					Data:         g,
					Source:       "cache",
					SourceDetail: SourceDetailModuleGreeterCache,
				}, nil
			}
			// Parse failure or stale schema → drop and re-read.
			_ = r.cache.DeleteModule(ctx, botID, guildID, "greeter")
		}
	}

	// Slow path: project just the module_greeter block.
	filter := bson.M{"bot_id": botID, "guild_id": guildID}
	projection := bson.M{"module_greeter": 1}
	var out struct {
		ModuleGreeter dbguild.ModuleGreeter `bson:"module_greeter"`
	}
	if err := r.coll.FindOne(ctx, filter, options.FindOne().SetProjection(projection)).Decode(&out); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return &Sourced[dbguild.ModuleGreeter]{
				Data:         dbguild.ModuleGreeter{},
				Source:       "db",
				SourceDetail: SourceDetailModuleGreeterDB,
			}, nil
		}
		return nil, err
	}

	g := out.ModuleGreeter
	if g.SchemaVersion == 0 {
		// Bloque inexistente: no hay nada del usuario que preservar.
		g = mocks.NewModuleGreeter()
	} else if g.SchemaVersion < dbguild.SchemaVersionGreeter {
		// Doc legacy CON config: rellenar los huecos sin pisar sus ajustes.
		// Sustituirlo por el mock aquí borraría la configuración del guild.
		//
		// El guard `< SchemaVersionGreeter` no es sólo un umbral de "hay algo
		// que rellenar": desde v13 es lo ÚNICO que evita reescalar `radius`
		// dos veces. NormalizeGreeter no sabe si ya se aplicó -reescala
		// cualquier radius no nulo que reciba, sin mirar la versión del
		// documento-, así que si esta llamada dejara de estar guardada por
		// versión, un doc ya migrado (radius en %) volvería a dividirse entre
		// la mitad de su lado corto en cada lectura y la redondez se iría
		// encogiendo (o deformando) sin fin.
		dbguild.NormalizeGreeter(&g)
	}

	if fields, err := redis.MarshalModuleGreeter(g); err == nil {
		_ = r.cache.SetModule(ctx, botID, guildID, "greeter", fields, redis.ModuleTTLSeconds)
	}

	return &Sourced[dbguild.ModuleGreeter]{
		Data:         g,
		Source:       "db",
		SourceDetail: SourceDetailModuleGreeterDB,
	}, nil
}

// Update applies the partial body to the greeter subdoc. The merge is
// `MergeDeepJSON` (recursive, presence-based): a body carrying
// `welcome.message.content` only touches that one leaf — none of the other
// welcome fields, goodbye, captcha, etc., get clobbered — and explicit
// `false`/`0`/`""`/`null` leaves are APPLIED, exactly like the Node
// `mergeDeep` (which only skips `undefined`).
//
// The Node service also runs `GuildRepository.checkGuildExists` first.
// We rely on Mongo's no-document response (returns nil, nil from
// FindOneAndUpdate) and emit `MODULE_NOT_FOUND` 400 from the handler.
func (r *ModuleGreeterRepository) Update(ctx context.Context, botID, guildID string, patch map[string]any) (*Sourced[dbguild.ModuleGreeter], error) {
	// Serialise the entire read-merge-write-cache cycle per guild.
	unlock := r.lockKey("greeter:" + botID + "\x00" + guildID)
	defer unlock()

	filter := bson.M{"bot_id": botID, "guild_id": guildID}
	var before struct {
		ModuleGreeter dbguild.ModuleGreeter `bson:"module_greeter"`
	}
	if err := r.coll.FindOne(ctx, filter).Decode(&before); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return nil, nil
		}
		return nil, fmt.Errorf("module greeter update (pre-read): %w", err)
	}

	// Merge into a copy so the caller's view is never half-merged.
	merged := before.ModuleGreeter
	if merged.SchemaVersion == 0 {
		merged = mocks.NewModuleGreeter()
	} else if merged.SchemaVersion < dbguild.SchemaVersionGreeter {
		// Se normaliza ANTES del merge: la línea 190 estampa
		// `SchemaVersion = SchemaVersionGreeter` al guardar, así que sin esto
		// el doc quedaba marcado como v11 sin haber ganado nunca los bloques
		// que v11 promete — y de forma irreversible, porque ningún camino
		// posterior vuelve a mirarlo.
		//
		// El mismo guard `< SchemaVersionGreeter` es, desde v13, la única
		// protección contra reescalar `radius` dos veces: NormalizeGreeter lo
		// reescala sin comprobar la versión del documento, así que llamarla
		// incondicionalmente sobre un doc ya migrado encogería (o
		// deformaría) la redondez en cada PATCH.
		dbguild.NormalizeGreeter(&merged)
	}
	if err := MergeDeepJSON(&merged, patch); err != nil {
		return nil, fmt.Errorf("module greeter update (merge): %w", err)
	}
	// Stamp server-side `updated_at` to `now` (UTC, millisecond precision)
	// AFTER the merge — the strict PATCH body rejects `updated_at`, and the
	// Node `mergeDeep({...data, updated_at: new Date()})` always overwrites it.
	merged.UpdatedAt = dbguild.NewDate(time.Now().UTC().Truncate(time.Millisecond))

	// `enabled_since` es WRITE-ONCE y EXCLUSIVAMENTE server-side.
	//
	// Se restaura primero el valor ALMACENADO, pisando lo que el merge haya
	// podido dejar: a diferencia de sus hermanos modmail/tempvoice, el PATCH
	// de greeter NO es de cuerpo estricto (`c.Bind().Body()` descarta las
	// claves desconocidas en silencio en vez de devolver 400), pero
	// `patchMap` reenvía el body CRUDO a `MergeDeepJSON`, que casa por tag
	// JSON. Sin esta línea, un cliente que enviara `enabled_since` se
	// auto-concedería derecho legacy permanente — decide quién paga, así que
	// la invariante se sostiene aquí, en el único write path del subdoc.
	merged.EnabledSince = before.ModuleGreeter.EnabledSince

	// Se estampa la PRIMERA vez que el módulo queda activado y no se
	// reescribe nunca: desactivar no lo borra y reactivar no lo pisa — el
	// derecho legacy se conserva para siempre (decisión de producto).
	if merged.Enabled && merged.EnabledSince == nil {
		stamp := dbguild.NewDate(time.Now().UTC().Truncate(time.Millisecond))
		merged.EnabledSince = &stamp
	}

	// Persist the merged doc — we send the entire module_greeter block
	// (cheaper to express, atomic, matches Mongoose's `markModified` +
	// `save` semantics from the Node side). Schema version is stamped
	// directly on the merged struct so we don't need a separate
	// `module_greeter.schema_version` key (which would conflict with
	// the parent `module_greeter` set in the same `$set`).
	merged.SchemaVersion = dbguild.SchemaVersionGreeter
	update := bson.M{
		"$set": bson.M{
			"module_greeter": merged,
		},
		"$currentDate": bson.M{"updatedAt": true},
	}
	opt2 := options.FindOneAndUpdate().SetReturnDocument(options.After)
	opt2 = opt2.SetProjection(bson.M{"module_greeter": 1})
	var after struct {
		ModuleGreeter dbguild.ModuleGreeter `bson:"module_greeter"`
	}
	if err := r.coll.FindOneAndUpdate(ctx, filter, update, opt2).Decode(&after); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return nil, nil
		}
		return nil, fmt.Errorf("module greeter update: %w", err)
	}

	if fields, err := redis.MarshalModuleGreeter(after.ModuleGreeter); err == nil {
		_ = r.cache.SetModule(ctx, botID, guildID, "greeter", fields, redis.ModuleTTLSeconds)
	}

	// The write may have flipped `enabled`, so the guild's enabled_modules
	// snapshot can no longer be trusted. See invalidateEnabledSnapshot.
	invalidateEnabledSnapshot(ctx, r.cache, botID, guildID, "greeter")

	return &Sourced[dbguild.ModuleGreeter]{
		Data:         after.ModuleGreeter,
		Source:       "db",
		SourceDetail: SourceDetailModuleGreeterDB,
	}, nil
}

// mapToModuleGreeter unmarshals a raw cache hash into the typed
// module. Best-effort: a parse failure returns the error so the caller
// can invalidate the cache and re-read from Mongo.
func mapToModuleGreeter(raw map[string]any, out *dbguild.ModuleGreeter) error {
	b, err := bson.Marshal(raw)
	if err != nil {
		return err
	}
	return bson.Unmarshal(b, out)
}

package dbguild

// Este fichero es el espejo de `DBModuleTts` en
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. El ORDEN de los
// campos sigue al del interfaz de TypeScript para que el cuerpo JSON salga con
// las claves en la misma secuencia que el resto de módulos. No hay generación
// automática entre los dos: si se toca uno, se toca el otro a mano.

// ModuleTTS es el espejo de `DBModuleTts`.
//
// NO hay canal de texto configurable a propósito: la superficie de lectura es
// el chat INTEGRADO del canal de voz donde está el bot, así que el canal se
// deduce del player y no se guarda. Antes existía un `channel_id`; se quitó
// porque obligaba a configurar dos cosas para que el módulo hiciera una.
//
// `RequiredRoleID` es puntero para que el JSON emita `null` (no `""`) cuando no
// hay rol exigido — la misma razón que `LogChannelID` en `ModuleAutomation`.
type ModuleTTS struct {
	SchemaVersion int  `bson:"schema_version" json:"schema_version"`
	Enabled       bool `bson:"enabled"        json:"enabled"`
	// EnabledSince es WRITE-ONCE, igual que en el resto de módulos: se estampa
	// en la primera activación y no se reescribe. `nil` = nunca activado.
	EnabledSince   *JSONDate `bson:"enabled_since,omitempty" json:"enabled_since"`
	RequireVoice   bool      `bson:"require_voice"    json:"require_voice"`
	Language       string    `bson:"language"         json:"language"`
	Speed          float64   `bson:"speed"            json:"speed"`
	SayName        bool      `bson:"say_name"         json:"say_name"`
	MaxChars       int       `bson:"max_chars"        json:"max_chars"`
	RepeatedChars  int       `bson:"repeated_chars"   json:"repeated_chars"`
	SkipEmoji      bool      `bson:"skip_emoji"       json:"skip_emoji"`
	RequiredRoleID *string   `bson:"required_role_id" json:"required_role_id"`
	// CommandsGlobal y Commands espejan `commands_global` / `commands` de
	// `DBModuleTts` (schema v2). Nunca `omitempty`: un mapa vacío tiene que
	// serializar como `{}` y una lista vacía como `[]`, jamás como `null`.
	CommandsGlobal TTSCommandAccess      `bson:"commands_global"  json:"commands_global"`
	Commands       map[string]TTSCommand `bson:"commands"         json:"commands"`
	UpdatedAt      JSONDate  `bson:"updated_at"       json:"updated_at"`
}

// Defaults y límites del módulo. Los techos NO son gusto propio: son los del
// nodo de síntesis, y pasarse de ellos no da audio, da rechazo.
const (
	DefaultTTSLanguage  = "es"
	DefaultTTSSpeed     = 1.0
	DefaultTTSMaxChars  = 200
	MaxTTSChars         = 300 // techo del nodo (KENA_LINK_TTS_MAX_CHARS)
	MinTTSSpeed         = 0.25
	MaxTTSSpeed         = 4.0
	MaxTTSRepeatedChars = 100
)

// TTSAccessMode espeja `DBAccessMode` (`"only" | "all_except"`): `only` es
// lista blanca, `all_except` lista negra. Con la lista vacía, `all_except`
// significa «todos» — que es el default y el comportamiento previo a v2.
type TTSAccessMode string

const (
	TTSAccessOnly      TTSAccessMode = "only"
	TTSAccessAllExcept TTSAccessMode = "all_except"
)

// TTSAccessList espeja `DBAccessList`.
type TTSAccessList struct {
	Mode TTSAccessMode `bson:"mode" json:"mode"`
	IDs  []string      `bson:"ids"  json:"ids"`
}

// TTSCommandAccess espeja `DBCommandAccess`: quién (roles) y dónde (canales o
// categorías) puede invocarse un subcomando.
type TTSCommandAccess struct {
	Roles      TTSAccessList `bson:"roles"      json:"roles"`
	Channels   TTSAccessList `bson:"channels"   json:"channels"`
	Categories TTSAccessList `bson:"categories" json:"categories"`
}

// TTSCommandSync espeja `DBTempVoiceCommandSync`: herencia POR EJE del acceso
// global. Un eje en `true` lee de `commands_global`; en `false`, del `access`
// propio del comando.
//
// A diferencia de music y tempvoice, aquí NO hay `UnmarshalJSON`/
// `UnmarshalBSONValue` que acepten el booleano legacy: aquellos módulos
// arrastran documentos anteriores a la expansión por eje, y TTS estrena el
// campo en v2 — no existe ni un documento con la forma vieja.
type TTSCommandSync struct {
	Roles      bool `bson:"roles"      json:"roles"`
	Channels   bool `bson:"channels"   json:"channels"`
	Categories bool `bson:"categories" json:"categories"`
}

// TTSCommand es una entrada de `commands`, con la misma forma que
// `DBTempVoiceCommand`.
type TTSCommand struct {
	Enabled   bool             `bson:"enabled"    json:"enabled"`
	UseGlobal TTSCommandSync   `bson:"use_global" json:"use_global"`
	Access    TTSCommandAccess `bson:"access"     json:"access"`
}

// TTSCommandNames son los subcomandos configurables de `/tts`, en el mismo
// orden que `TTS_COMMANDS` del dashboard y que el `SlashCommandBuilder` de
// `tts-module`. Mantener los tres en sync: un nombre que no case aquí deja el
// comando sin fila en el panel y sin gate en el módulo.
//
// `help` y `ping` quedan fuera a propósito: son andamiaje genérico de la
// plantilla de módulo, no superficie de TTS (music tampoco los lista).
var TTSCommandNames = []string{
	"join",
	"leave",
	"skip",
	"language",
}

// TTSCommandAccessDefault: sin restricción en los tres ejes. Slices nuevos en
// cada llamada para que dos documentos no compartan el mismo array.
func TTSCommandAccessDefault() TTSCommandAccess {
	return TTSCommandAccess{
		Roles:      TTSAccessList{Mode: TTSAccessAllExcept, IDs: []string{}},
		Channels:   TTSAccessList{Mode: TTSAccessAllExcept, IDs: []string{}},
		Categories: TTSAccessList{Mode: TTSAccessAllExcept, IDs: []string{}},
	}
}

// TTSConfigurableCommandDefault: activo y heredando el acceso global en los
// tres ejes — el comportamiento que TTS tenía antes de existir este campo.
func TTSConfigurableCommandDefault() TTSCommand {
	return TTSCommand{
		Enabled:   true,
		UseGlobal: TTSCommandSync{Roles: true, Channels: true, Categories: true},
		Access:    TTSCommandAccessDefault(),
	}
}

// DefaultTTSCommands siembra una entrada por subcomando. Mapa y slices nuevos
// en cada llamada.
func DefaultTTSCommands() map[string]TTSCommand {
	out := make(map[string]TTSCommand, len(TTSCommandNames))
	for _, name := range TTSCommandNames {
		out[name] = TTSConfigurableCommandDefault()
	}
	return out
}

// NormalizeTTS deja el módulo en la forma que el resto del sistema da por
// hecha. Idempotente.
//
// Corrige EXCLUSIVAMENTE el cero de Go en los tres campos cuyo valor de fábrica
// no es el cero de su tipo y para los que el cero no significa nada
// (`language: ""`, `speed: 0`, `max_chars: 0` son documentos parciales o
// entradas de caché viejas, no configuraciones). No es validación: `false` y `0`
// son legítimos en el resto de campos y se respetan tal cual.
//
// El acceso por comando (v2) SÍ se siembra aquí, y es deliberado: TTS no pasa
// por `bson.M` + `Migrate*Raw` como music o tempvoice —su repositorio decodifica
// directo al struct—, así que este es el único punto por el que pasan tanto un
// documento viejo (sin los campos) como uno nuevo. Sembrar una entrada AUSENTE
// no pisa configuración: sólo aparece cuando el subcomando aún no se había
// guardado nunca. Desactivar un comando escribe `enabled: false` con la clave
// presente, y una clave presente no se toca.
//
// `RequireVoice` y `SayName` NO se normalizan aunque su default sea `true`: el
// cero de Go es `false`, así que rellenarlos aquí haría imposible desactivarlos
// —cada lectura los volvería a encender—. Su siembra la hace el mock de fábrica
// (`mocks.NewModuleTTS`), que es el único sitio donde «no hay valor» y «hay un
// `false` explícito» se distinguen.
func NormalizeTTS(m *ModuleTTS) {
	if m == nil {
		return
	}
	if m.Language == "" {
		m.Language = DefaultTTSLanguage
	}
	if m.Speed == 0 {
		m.Speed = DefaultTTSSpeed
	}
	if m.MaxChars == 0 {
		m.MaxChars = DefaultTTSMaxChars
	}
	normalizeTTSAccess(&m.CommandsGlobal)
	if m.Commands == nil {
		m.Commands = make(map[string]TTSCommand, len(TTSCommandNames))
	}
	// Backfill por nombre, no sólo del mapa entero: así un subcomando nuevo
	// nace activo en los documentos que ya existían, sin migración aparte.
	for _, name := range TTSCommandNames {
		if _, ok := m.Commands[name]; !ok {
			m.Commands[name] = TTSConfigurableCommandDefault()
		}
	}
	for name, cmd := range m.Commands {
		normalizeTTSAccess(&cmd.Access)
		m.Commands[name] = cmd
	}
}

// normalizeTTSAccess repone el modo en blanco y las listas nil de los tres
// ejes. El cero de Go de `Mode` es `""`, que no es un modo válido: sin esto,
// un bloque de acceso decodificado de un documento parcial diría «lista blanca
// vacía» —es decir, nadie— en vez de «todos».
func normalizeTTSAccess(a *TTSCommandAccess) {
	normalizeTTSAccessList(&a.Roles)
	normalizeTTSAccessList(&a.Channels)
	normalizeTTSAccessList(&a.Categories)
}

func normalizeTTSAccessList(l *TTSAccessList) {
	if l.Mode == "" {
		l.Mode = TTSAccessAllExcept
	}
	if l.IDs == nil {
		l.IDs = []string{}
	}
}

