	if c == nil {
		return nil
	}

	if err := validateGreeterMessageMode(c.Message.Mode, prefix+"message.mode"); err != nil {
		return err
	}
	if err := maxLen(&c.Message.Content, maxGreeterContent, prefix+"message.content"); err != nil {
