// ttsAccessModeMsg + validateTTSAccessMode cierran el enum `mode` de un
// `DBAccessList`: `""` se acepta -es lo que decodifica un bloque parcial que
// no tocó el campo, y `NormalizeTTS` (incondicional en cada escritura, ver
// module_tts_repository.go) lo repone a `all_except` justo después del
// merge- pero cualquier OTRO valor es imposible: el bot sólo sabe leer
// `only`/`all_except`, así que un `mode: "banana"` se guardaba tal cual y
// dejaba el gate del subcomando en un estado que nadie sabe interpretar.
const ttsAccessModeMsg = `Invalid option: expected one of "only"|"all_except"`

func validateTTSAccessMode(mode dbguild.TTSAccessMode, property string) *apierrors.CustomError {
	if mode == "" || mode == dbguild.TTSAccessOnly || mode == dbguild.TTSAccessAllExcept {
		return nil
	}
	return zodItemError(ttsAccessModeMsg, property)
}

func validateTTSAccessList(l *dbguild.TTSAccessList, prefix string) *apierrors.CustomError {
	return validateTTSAccessMode(l.Mode, prefix+"mode")
}

