175	// punto final (p.ej. "welcome.image." o "welcome.dm.image."), igual que hace
176	// validateGreeterEmbed con el suyo.
177	func validateGreeterImage(img *dbguild.GreeterImage, prefix string) *apierrors.CustomError {
178		if err := validateGreeterImageMode(img.Mode, prefix+"mode"); err != nil {
179			return err
180		}
181		if err := maxLen(img.BackgroundURL, maxGreeterURL, prefix+"background_url"); err != nil {
182			return err
183		}
184	
185		canvas := &img.Canvas
186		if canvas.Width > maxCanvasSide || canvas.Height > maxCanvasSide {
187			return zodItemError(
188				"Too big: expected number to be <="+strconv.Itoa(maxCanvasSide),
189				prefix+"canvas",
190			)
191		}
192		if canvas.Width < 0 || canvas.Height < 0 {
193			return zodItemError("Too small: expected number to be >=0", prefix+"canvas")
194		}
195		if len(canvas.Elements) > maxCanvasElements {
196			return zodItemError(
197				"Too big: expected array to have <="+strconv.Itoa(maxCanvasElements)+" items",
198				prefix+"canvas.elements",
199			)
200		}
201		if err := maxLen(
202			canvas.BackgroundURL,
203			maxGreeterURL,
204			prefix+"canvas.background_url",
205		); err != nil {
206			return err
207		}
208		for i := range canvas.Elements {
209			if err := maxLen(
210				canvas.Elements[i].URL,
211				maxGreeterURL,
212				prefix+"canvas.elements."+strconv.Itoa(i)+".url",
213			); err != nil {
214				return err
215			}
216		}
217		return nil
218	}
219	
220	func validateGreeterMessageConfig(
221		c *dbguild.GreeterMessageConfig,
222		prefix string,
223	) *apierrors.CustomError {
224		if c == nil {
225			return nil
226		}
227	
228		if err := validateGreeterMessageMode(c.Message.Mode, prefix+"message.mode"); err != nil {
229			return err
230		}
231		if err := maxLen(&c.Message.Content, maxGreeterContent, prefix+"message.content"); err != nil {
232			return err
233		}
234		if err := validateGreeterEmbed(&c.Embed, prefix+"embed."); err != nil {
235			return err
236		}
237		if err := validateGreeterMessageMode(c.DM.Message.Mode, prefix+"dm.message.mode"); err != nil {
238			return err
239		}
240		if err := maxLen(&c.DM.Message.Content, maxGreeterContent, prefix+"dm.message.content"); err != nil {
241			return err
242		}
243		if err := validateGreeterEmbed(&c.DM.Embed, prefix+"dm.embed."); err != nil {
244			return err
245		}
246		if err := inRange(
247			c.Behavior.DeleteAfterSeconds,
248			maxDelaySeconds,
249			prefix+"behavior.delete_after_seconds",
250		); err != nil {
251			return err
252		}
253		if err := inRange(
254			c.DM.DeleteAfterSeconds,
255			maxDelaySeconds,
256			prefix+"dm.delete_after_seconds",
257		); err != nil {
258			return err
259		}
260		// El canvas de privado puede llegar por PATCH directo igual que el de
261		// canal -nada en el transporte los distingue-, así que se valida con los
262		// mismos topes. Ver validateGreeterImage.
263		if err := validateGreeterImage(&c.Image, prefix+"image."); err != nil {
264			return err
265		}
266		if err := validateGreeterImage(&c.DM.Image, prefix+"dm.image."); err != nil {
267			return err
268		}
269		return nil
270	}
271	
272	// ValidateUpdateModuleGreeter aplica los topes y los enums que faltaban por
273	// completo en el servidor. El zod del dashboard sí revalida en su propio
274	// servidor, pero eso sólo cubre a quien entra POR el dashboard: este
275	// endpoint acepta un PATCH directo con la credencial de api-db y no tenía
276	// nada que lo parase.
277	//
278	// Los enums (`message.mode`, `image.mode`) aceptan `""` -es lo que decodifica
279	// un bloque parcial que no tocó el campo, y `NormalizeGreeter` lo repone a su
280	// default justo después del merge- pero rechazan cualquier OTRO valor fuera
281	// del catálogo: guardar `mode: "banana"` no es «configuración rara», es una
282	// bienvenida que ni el bot ni el dashboard saben renderizar, y antes de este
283	// chequeo se persistía tal cual.
284	//
285	// Sólo mira lo que el cuerpo trae: `UpdateModuleGreeterBody` es un parcial y
286	// un puntero nil significa «no tocar este bloque», no «vacío».
287	func ValidateUpdateModuleGreeter(body *UpdateModuleGreeterBody) *apierrors.CustomError {
288		for _, b := range []struct {
289			config *dbguild.GreeterMessageConfig
290			prefix string
291		}{
292			{body.Welcome, "welcome."},
293			{body.Goodbye, "goodbye."},
294			{body.Boost, "boost."},
295		} {
296			if err := validateGreeterMessageConfig(b.config, b.prefix); err != nil {
297				return err
298			}
299		}
300	
301		if body.JoinRoles != nil {
302			if len(body.JoinRoles.RolesID) > maxJoinRoles {
303				return zodItemError(
304					"Too big: expected array to have <="+strconv.Itoa(maxJoinRoles)+" items",
305					"join_roles.roles_id",
306				)
307			}
308			if err := inRange(
309				body.JoinRoles.DelaySeconds,
310				maxDelaySeconds,
311				"join_roles.delay_seconds",
312			); err != nil {
313				return err
314			}
315		}
316	
317		if body.Captcha != nil {
318			if err := maxLen(
319				&body.Captcha.ButtonLabel,
320				maxGreeterButtonLabel,
321				"captcha.button_label",
322			); err != nil {
323				return err
324			}
325			if e := body.Captcha.WelcomeEmbed; e != nil {
326				if err := maxLen(&e.Title, maxGreeterEmbedTitle, "captcha.welcome_embed.title"); err != nil {
327					return err
328				}
329				if err := maxLen(
330					&e.Description,
331					maxGreeterEmbedDesc,
332					"captcha.welcome_embed.description",
333				); err != nil {
